import { motion } from 'framer-motion';
import { Link } from 'react-router-dom';

const services = [
  {
    icon: '🕊️', title: 'Anxiety Support', color: '#EDD5D0',
    desc: 'Gentle, evidence-based tools to quiet the anxious mind and build lasting inner calm. We work with generalized anxiety, social anxiety, panic, and worry.',
    includes: ['Cognitive reframing', 'Breathing practices', 'Nervous system regulation', 'Worry management'],
  },
  {
    icon: '💗', title: 'Emotional Healing', color: '#DDB7B0',
    desc: 'Process old wounds, grief, and heartbreak with compassion and professional care. Heal what has been hidden and reclaim your wholeness.',
    includes: ['Grief processing', 'Trauma-informed support', 'Emotional release', 'Forgiveness work'],
  },
  {
    icon: '🌿', title: 'Stress Management', color: '#D4DCCF',
    desc: 'Restore balance to an overwhelmed nervous system and build sustainable resilience for life\'s inevitable pressures.',
    includes: ['Stress mapping', 'Boundary setting', 'Rest practices', 'Lifestyle rebalancing'],
  },
  {
    icon: '📚', title: 'Student Counseling', color: '#EAD9A8',
    desc: 'Navigate academic pressure, identity exploration, transitions, and the unique emotional challenges of student life.',
    includes: ['Academic stress', 'Identity & belonging', 'Life transitions', 'Future anxiety'],
  },
  {
    icon: '🌸', title: 'Relationship Guidance', color: '#EDD5D0',
    desc: 'Heal relational patterns, improve communication, and cultivate deeper, more loving and secure connections.',
    includes: ['Attachment patterns', 'Communication skills', 'Conflict resolution', 'Healthy boundaries'],
  },
  {
    icon: '✨', title: 'Self-Esteem Therapy', color: '#DDB7B0',
    desc: 'Rediscover your inherent worth, rebuild confidence from within, and step fully into the person you were always meant to be.',
    includes: ['Inner critic work', 'Self-compassion', 'Identity building', 'Confidence practices'],
  },
  {
    icon: '🧘', title: 'Mindfulness Wellness', color: '#D4DCCF',
    desc: 'Anchor to the present moment with beautiful, grounding mindfulness and meditation practices designed for real life.',
    includes: ['Guided meditation', 'Body awareness', 'Present-moment tools', 'Emotional grounding'],
  },
];

const ServicesPage = () => (
  <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
    {/* Hero */}
    <section style={{ padding: '140px 2rem 80px', textAlign: 'center', position: 'relative', zIndex: 2 }}>
      <div style={{
        position: 'absolute', top: 0, left: '50%', transform: 'translateX(-50%)',
        width: '600px', height: '400px',
        background: 'radial-gradient(ellipse, rgba(221,183,176,0.12) 0%, transparent 70%)',
        zIndex: 1,
      }} />
      <motion.div
        initial={{ opacity: 0, y: 30 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.8 }}
        style={{ position: 'relative', zIndex: 2 }}
      >
        <div style={{ fontFamily: 'Manrope', fontSize: '0.75rem', letterSpacing: '0.15em', color: '#B8C4B2', textTransform: 'uppercase', marginBottom: '1rem' }}>
          Healing Offerings
        </div>
        <h1 style={{ fontFamily: 'Cormorant Garamond, serif', fontSize: 'clamp(2.5rem, 5vw, 4rem)', fontWeight: 600, color: '#3D2B38', lineHeight: 1.2, marginBottom: '1.2rem' }}>
          Our Services
        </h1>
        <p style={{ fontFamily: 'Manrope', fontSize: '1rem', color: '#9B7A8A', lineHeight: 1.9, maxWidth: '580px', margin: '0 auto' }}>
          Each service is crafted with deep care to meet you exactly where you are on your emotional journey.
        </p>
      </motion.div>
    </section>

    {/* Services Grid */}
    <section style={{ padding: '40px 2rem 100px', position: 'relative', zIndex: 2 }}>
      <div style={{ maxWidth: '1200px', margin: '0 auto' }}>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))', gap: '2rem' }}>
          {services.map((s, i) => (
            <motion.div
              key={s.title}
              initial={{ opacity: 0, y: 30 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ delay: i * 0.08, duration: 0.7 }}
              whileHover={{ y: -6, boxShadow: '0 24px 60px rgba(221,183,176,0.2)' }}
              style={{
                background: 'rgba(255,253,252,0.75)',
                backdropFilter: 'blur(16px)',
                border: '1px solid rgba(221,183,176,0.15)',
                borderRadius: '24px',
                overflow: 'hidden',
                transition: 'all 0.35s',
                cursor: 'default',
              }}
            >
              <div style={{ height: '6px', background: s.color, opacity: 0.8 }} />
              <div style={{ padding: '2rem' }}>
                <div style={{ fontSize: '2.5rem', marginBottom: '1rem' }}>{s.icon}</div>
                <h3 style={{ fontFamily: 'Cormorant Garamond, serif', fontSize: '1.4rem', fontWeight: 600, color: '#3D2B38', marginBottom: '0.8rem' }}>
                  {s.title}
                </h3>
                <p style={{ fontFamily: 'Manrope', fontSize: '0.87rem', color: '#9B7A8A', lineHeight: 1.8, marginBottom: '1.3rem' }}>
                  {s.desc}
                </p>
                <div style={{ borderTop: '1px solid rgba(221,183,176,0.15)', paddingTop: '1rem' }}>
                  <div style={{ fontFamily: 'Manrope', fontSize: '0.72rem', letterSpacing: '0.1em', color: '#B8C4B2', textTransform: 'uppercase', marginBottom: '0.7rem' }}>
                    What We Work On
                  </div>
                  <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.5rem' }}>
                    {s.includes.map(item => (
                      <div key={item} style={{
                        background: s.color + '30',
                        border: `1px solid ${s.color}60`,
                        borderRadius: '50px',
                        padding: '3px 12px',
                        fontFamily: 'Manrope',
                        fontSize: '0.73rem',
                        color: '#9B7A8A',
                      }}>
                        {item}
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </motion.div>
          ))}
        </div>
      </div>
    </section>

    {/* CTA */}
    <section style={{ padding: '60px 2rem 100px', textAlign: 'center', position: 'relative', zIndex: 2 }}>
      <motion.div
        initial={{ opacity: 0, y: 30 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true }}
        style={{
          maxWidth: '600px',
          margin: '0 auto',
          background: 'rgba(255,253,252,0.6)',
          backdropFilter: 'blur(16px)',
          border: '1px solid rgba(221,183,176,0.2)',
          borderRadius: '28px',
          padding: '3rem',
        }}
      >
        <div style={{ fontSize: '2rem', marginBottom: '1rem' }}>🌷</div>
        <h2 style={{ fontFamily: 'Cormorant Garamond, serif', fontSize: '2rem', color: '#3D2B38', fontWeight: 600, marginBottom: '0.8rem' }}>
          Not Sure Where to Start?
        </h2>
        <p style={{ fontFamily: 'Manrope', fontSize: '0.9rem', color: '#9B7A8A', lineHeight: 1.8, marginBottom: '1.8rem' }}>
          Your first session is a gentle discovery conversation. We will explore together what support feels right for you.
        </p>
        <Link to="/book">
          <motion.button
            whileHover={{ scale: 1.05, boxShadow: '0 12px 40px rgba(221,183,176,0.45)' }}
            style={{
              background: 'linear-gradient(135deg, #DDB7B0, #D6BE8A)',
              color: '#FFFDFC',
              border: 'none',
              borderRadius: '50px',
              padding: '14px 36px',
              fontFamily: 'Manrope',
              fontSize: '0.9rem',
              fontWeight: 600,
              cursor: 'pointer',
            }}
          >
            Book a Discovery Session
          </motion.button>
        </Link>
      </motion.div>
    </section>
  </motion.div>
);

export default ServicesPage;
